// frontend-react/src/components/CreateDynamicForm.js
import React, { useState, useEffect } from 'react';
import {
    TextField,
    Button,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    Tabs,
    Tab,
    Box,
    IconButton,
} from '@mui/material';
import { Select, MenuItem, Chip } from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';

export default function CreateDynamicForm() {
    const [rows, setRows] = useState([]);
    const [formName, setFormName] = useState('');
    const [formDescription, setFormDescription] = useState('');
    const [savedForms, setSavedForms] = useState([]);
    const [tab, setTab] = useState(0);

    useEffect(() => {
        // Load saved forms from local storage on component mount (for development/testing)
        const storedForms = JSON.parse(localStorage.getItem('savedForms')) || [];
        setSavedForms(storedForms);
        console.log('Manage Dynamic form', storedForms);
    }, []);

    const controlTypes = [
        'text', 'password', 'email', 'search', 'tel', 'url', 'number', 'date',
        'datetime-local', 'month', 'time', 'week', 'checkbox', 'radio', 'range',
        'color', 'file', 'hidden', 'submit', 'reset', 'button', 'image',
    ];

    const validationOptions = [
        { value: '', label: 'None' },
        { value: 'required', label: 'Required' },
        { value: 'email', label: 'Valid Email' },
        { value: 'phone', label: 'Valid Phone Number' },
        { value: 'numeric', label: 'Numbers Only' },
        { value: 'alphabetic', label: 'Alphabets Only' },
        { value: 'alphanumeric', label: 'Alphanumeric Only' },
        { value: 'url', label: 'Valid URL' },
        { value: 'password-strong', label: 'Strong Password' },
        { value: 'min-length', label: 'Minimum Length' },
        { value: 'max-length', label: 'Maximum Length' },
        { value: 'match', label: 'Must Match Another Field' },
        { value: 'date-future', label: 'Date Should Be in Future' },
        { value: 'date-past', label: 'Date Should Be in Past' },
        { value: 'no-spaces', label: 'No Spaces Allowed' },
        { value: 'positive-number', label: 'Positive Numbers Only' },
        { value: 'whole-number', label: 'Whole Numbers Only' },
        { value: 'exact-length', label: 'Exact Character Length' },
    ];

    const addRow = () => {
        setRows([
            ...rows,
            {
                label: '',
                controlType: 'text',
                placeholder: '',
                errorMessage: '',
                minLength: '',
                maxLength: '',
                optionsCount: 0,
                options: [],
                validations: [],
                available: true,
            },
        ]);
    };

    const deleteRow = (index) => {
        const updatedRows = rows.filter((_, idx) => idx !== index);
        setRows(updatedRows);
    };

    const moveRow = (index, direction) => {
        const newRows = [...rows];
        const targetIndex = direction === 'up' ? index - 1 : index + 1;
        if (targetIndex < 0 || targetIndex >= newRows.length) return;
        const temp = newRows[targetIndex];
        newRows[targetIndex] = newRows[index];
        newRows[index] = temp;
        setRows(newRows);
    };

    const updateRow = (index, field, value) => {
        const updatedRows = rows.map((row, idx) => {
            if (idx === index) {
                const updatedRow = { ...row, [field]: value };

                if (field === 'controlType') {
                    // Reset dependent fields when controlType changes
                    updatedRow.minLength = '';
                    updatedRow.maxLength = '';
                    updatedRow.optionsCount = 0;
                    updatedRow.options = [];
                }

                return updatedRow;
            }
            return row;
        });
        setRows(updatedRows);
    };

    const updateOptionsCount = (index, count) => {
        const updatedRows = rows.map((row, idx) => {
            if (idx === index) {
                const options = Array.from({ length: Number(count) }, (_, i) => row.options[i] || '');
                return { ...row, optionsCount: count, options };
            }
            return row;
        });
        setRows(updatedRows);
    };

    const updateOptionValue = (rowIndex, optionIndex, value) => {
        const updatedRows = [...rows];
        updatedRows[rowIndex].options[optionIndex] = value;
        setRows(updatedRows);
    };

    const handleSave = async () => {
        if (!formName.trim()) {
            alert('Form Name is required!');
            return;
        }

        const formDetails = { formName, formDescription, fields: rows };

        try {
            const response = await fetch('http://localhost:5000/api/save-form', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(formDetails),
            });

            if (response.ok) {
                const data = await response.json();
                alert('Form saved to database successfully!');
                console.log('Form ID:', data.formId);
                handleNewForm(); // Clear the form after successful save
            } else {
                const errorData = await response.json();
                console.error('Failed to save form:', errorData);
                alert('Failed to save form to database.');
            }
        } catch (error) {
            console.error('There was an error saving the form:', error);
            alert('There was an error saving the form.');
        }

        // Optional: Save to local storage as well (for development/testing)
        const updatedForms = [
            ...savedForms.filter((f) => f.formName !== formName),
            formDetails,
        ];
        localStorage.setItem('savedForms', JSON.stringify(updatedForms));
        setSavedForms(updatedForms);
        console.log('Saved to local storage:', updatedForms);
    };

    const handleNewForm = () => {
        setFormName('');
        setFormDescription('');
        setRows([]);
    };

    return (
        <div style={{ padding: 24 }}>
            <Tabs value={tab} onChange={(e, newValue) => setTab(newValue)}>
                <Tab label="Create Dynamic Form" />
            </Tabs>

            {tab === 0 && (
                <div>
                    <Box display="flex" gap={2} marginTop={2} marginBottom={2}>
                        <TextField
                            label="Form Name *"
                            value={formName}
                            onChange={(e) => setFormName(e.target.value)}
                            variant="outlined"
                            size="small"
                            required
                            fullWidth
                        />
                        <TextField
                            label="Form Description"
                            value={formDescription}
                            onChange={(e) => setFormDescription(e.target.value)}
                            variant="outlined"
                            size="small"
                            multiline
                            rows={2}
                            fullWidth
                        />
                    </Box>

                    <Button variant="contained" color="secondary" onClick={handleNewForm} style={{ marginBottom: 16, marginRight: 8 }}>
                        New Form
                    </Button>

                    <Button variant="contained" color="primary" onClick={addRow} style={{ marginBottom: 16 }}>
                        Add Row
                    </Button>

                    <TableContainer component={Paper} style={{ marginBottom: 16 }}>
                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell>Label</TableCell>
                                    <TableCell>Control Type</TableCell>
                                    <TableCell>Placeholder / Help Text</TableCell>
                                    <TableCell>Error Message</TableCell>
                                    <TableCell>Extra Options</TableCell>
                                    <TableCell>Choose Validation</TableCell>
                                    <TableCell>Actions</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {rows.map((row, index) => (
                                    <TableRow key={index}>
                                        <TableCell>
                                            <TextField
                                                value={row.label}
                                                onChange={(e) => updateRow(index, 'label', e.target.value)}
                                                size="small"
                                            />
                                        </TableCell>
                                        <TableCell>
                                            <TextField
                                                select
                                                SelectProps={{ native: true }}
                                                value={row.controlType}
                                                onChange={(e) => updateRow(index, 'controlType', e.target.value)}
                                                size="small"
                                            >
                                                {controlTypes.map((type) => (
                                                    <option key={type} value={type}>{type}</option>
                                                ))}
                                            </TextField>
                                        </TableCell>
                                        <TableCell>
                                            <TextField
                                                value={row.placeholder}
                                                onChange={(e) => updateRow(index, 'placeholder', e.target.value)}
                                                size="small"
                                            />
                                        </TableCell>
                                        <TableCell>
                                            <TextField
                                                value={row.errorMessage}
                                                onChange={(e) => updateRow(index, 'errorMessage', e.target.value)}
                                                size="small"
                                            />
                                        </TableCell>
                                        <TableCell>
                                            {['text', 'password', 'number'].includes(row.controlType) && (
                                                <Box display="flex" flexDirection="column" gap={1}>
                                                    <TextField
                                                        label="Min Length"
                                                        type="number"
                                                        value={row.minLength}
                                                        onChange={(e) => updateRow(index, 'minLength', e.target.value)}
                                                        size="small"
                                                    />
                                                    <TextField
                                                        label="Max Length"
                                                        type="number"
                                                        value={row.maxLength}
                                                        onChange={(e) => updateRow(index, 'maxLength', e.target.value)}
                                                        size="small"
                                                    />
                                                </Box>
                                            )}

                                            {['checkbox', 'radio'].includes(row.controlType) && (
                                                <Box display="flex" flexDirection="column" gap={1}>
                                                    <TextField
                                                        label="Number of Options"
                                                        type="number"
                                                        value={row.optionsCount}
                                                        onChange={(e) => updateOptionsCount(index, e.target.value)}
                                                        size="small"
                                                    />
                                                    {Array.from({ length: Number(row.optionsCount) }).map((_, optIdx) => (
                                                        <TextField
                                                            key={optIdx}
                                                            label={`Option ${optIdx + 1}`}
                                                            value={row.options[optIdx] || ''}
                                                            onChange={(e) => updateOptionValue(index, optIdx, e.target.value)}
                                                            size="small"
                                                        />
                                                    ))}
                                                </Box>
                                            )}
                                        </TableCell>
                                        <TableCell>
                                            <Select
                                                multiple
                                                displayEmpty
                                                value={row.validations}
                                                onChange={(e) => updateRow(index, 'validations',
                                                    typeof e.target.value === 'string' ? e.target.value.split(',') : e.target.value
                                                )}
                                                renderValue={(selected) => (
                                                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                                                        {selected.length === 0 ? (
                                                            <em>Select Validations</em>
                                                        ) : (
                                                            selected.map((value) => (
                                                                <Chip key={value} label={validationOptions.find(opt => opt.value === value)?.label || value} />
                                                            ))
                                                        )}
                                                    </Box>
                                                )}
                                                size="small"
                                                fullWidth
                                            >
                                                {validationOptions.map((option) => (
                                                    <MenuItem key={option.value} value={option.value}>
                                                        {option.label}
                                                    </MenuItem>
                                                ))}
                                            </Select>
                                        </TableCell>
                                        <TableCell>
                                            <IconButton onClick={() => moveRow(index, 'up')}>
                                                <ArrowUpwardIcon fontSize="small" />
                                            </IconButton>
                                            <IconButton onClick={() => moveRow(index, 'down')}>
                                                <ArrowDownwardIcon fontSize="small" />
                                            </IconButton>
                                            <IconButton onClick={() => deleteRow(index)}>
                                                <DeleteIcon fontSize="small" />
                                            </IconButton>
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </TableContainer>

                    <Button variant="contained" color="primary" onClick={handleSave}>
                        Save Form
                    </Button>
                </div>
            )}
        </div>
    );
}
